        assert_eq!(dir, PathBuf::from("/tmp/ws/lightfast/feat__auth"));
    }

    #[test]
    fn workspace_id_format() {
        assert_eq!(workspace_id("lightfast", "main"), "lightfast-main");
        assert_eq!(
            workspace_id("lightfast", "feat/auth"),
            "lightfast-feat__auth"
        );
    }

