 314→            None => {
 315→                error!("could not detect workspace from current directory");
 316→                info!("Usage: dual launch [workspace]");
 317→                return 1;
 318→            }
 319→        }
 320→    };
 321→
 322→    let workspace_root = st.workspace_root();
 323→    let container_name = config::container_name(&entry.repo, &entry.branch);
 324→    let session_name = config::session_name(&entry.repo, &entry.branch);
 325→    debug!(
 326→        repo = %entry.repo,
 327→        branch = %entry.branch,
 328→        "resolved workspace"
 329→    );
 330→
 331→    // Step 1: Resolve workspace directory
 332→    let workspace_dir = if let Some(ref path) = entry.path {
 333→        let dir = PathBuf::from(path);
 334→        if !dir.join(".git").exists() {
 335→            error!(
 336→                "workspace path {} does not contain a git repo",
 337→                dir.display()
 338→            );
 339→            return 1;
 340→        }
 341→        dir
 342→    } else {
 343→        // Try to clone from local main workspace first (fast, hardlinks)
 344→        let target_dir = config::workspace_dir(&workspace_root, &entry.repo, &entry.branch);
 345→        let main_workspace_path = st
 346→            .workspaces_for_repo(&entry.repo)
 347→            .into_iter()
 348→            .find(|ws| ws.path.is_some())
 349→            .and_then(|ws| ws.path.as_ref().map(PathBuf::from));
 350→
 351→        match main_workspace_path {
 352→            Some(main_path) if main_path.join(".git").exists() => {
 353→                info!("Cloning from local main workspace...");
 354→                match clone::clone_from_local(&main_path, &target_dir, &entry.branch) {
 355→                    Ok(dir) => dir,
 356→                    Err(e) => {
 357→                        error!("local clone failed: {e}");
 358→                        return 1;
 359→                    }
 360→                }
 361→            }
 362→            _ => {
 363→                // Fallback: clone from remote URL
 364→                match clone::clone_workspace(
 365→                    &workspace_root,
 366→                    &entry.repo,
 367→                    &entry.url,
 368→                    &entry.branch,
 369→                ) {
 370→                    Ok(dir) => dir,
 371→                    Err(e) => {
 372→                        error!("clone failed: {e}");
 373→                        return 1;
 374→                    }
 375→                }
 376→            }
 377→        }
 378→    };
 379→
 380→    // Step 2: Handle shared files
 381→    let hints = config::load_hints(&workspace_dir).unwrap_or_default();
 382→    if let Some(ref shared_config) = hints.shared
 383→        && !shared_config.files.is_empty()
 384→        && let Ok(shared_dir) = shared::ensure_shared_dir(&entry.repo)
 385→    {
 386→        if entry.path.is_some() {
 387→            // Main workspace: ensure shared files are initialized
 388→            match shared::init_from_main(&workspace_dir, &shared_dir, &shared_config.files) {
 389→                Ok(moved) => {
 390→                    for f in &moved {
 391→                        info!("  shared: {f} → ~/.dual/shared/{}/", entry.repo);
 392→                    }
 393→                }
 394→                Err(e) => warn!("shared init failed: {e}"),
 395→            }
 396→        } else {
 397→            // Branch workspace: copy shared files
 398→            match shared::copy_to_branch(&workspace_dir, &shared_dir, &shared_config.files) {
 399→                Ok(copied) => {
 400→                    for f in &copied {
 401→                        info!("  shared: copied {f}");
 402→                    }
 403→                }
 404→                Err(e) => warn!("shared copy failed: {e}"),
 405→            }
 406→        }
 407→    }
 408→
 409→    // Step 3: Ensure container exists and is running
 410→    let is_new_container = matches!(
 411→        container::status(&container_name),
 412→        container::ContainerStatus::Missing
 413→    );
 414→    match container::status(&container_name) {
 415→        container::ContainerStatus::Missing => {
 416→            // Build image from Dockerfile if configured
 417→            let effective_image = if let Some(ref build) = hints.dockerfile {
 418→                let image_tag = format!("dual-build-{container_name}");
 419→                info!("Building image from Dockerfile...");
 420→                match container::build_image(&image_tag, &workspace_dir, build) {
 421→                    Ok(tag) => tag,
 422→                    Err(e) => {
 423→                        error!("docker build failed: {e}");
 424→                        return 1;
 425→                    }
 426→                }
 427→            } else {
 428→                hints.image.clone()
 429→            };
 430→
 431→            info!("Creating container {container_name}...");
 432→            if let Err(e) = container::create(
 433→                &container_name,
 434→                &workspace_dir,
 435→                &effective_image,
 436→                &hints.env,
 437→                &hints.anonymous_volumes,
 438→            ) {
 439→                error!("container create failed: {e}");
 440→                return 1;
 441→            }
 442→            if let Err(e) = container::start(&container_name) {
 443→                error!("container start failed: {e}");
 444→                return 1;
 445→            }
 446→        }
 447→        container::ContainerStatus::Stopped => {
 448→            info!("Starting container {container_name}...");
 449→            if let Err(e) = container::start(&container_name) {
 450→                error!("container start failed: {e}");
 451→                return 1;
 452→            }
 453→        }
 454→        container::ContainerStatus::Running => {}
 455→    }
 456→
 457→    // Step 3.5: Run setup command on new containers
 458→    if is_new_container && let Some(ref setup) = hints.setup {
 459→        info!("Running setup: {setup}");
 460→        if let Err(e) = container::exec_setup(&container_name, setup) {
 461→            error!("setup failed: {e}");
 462→            return 1;
 463→        }
 464→    }
 465→
 466→    // Step 4: Write shell RC file
 467→    let rc_path = match shell::write_rc_file(&container_name, &hints.extra_commands) {
 468→        Ok(p) => p,
 469→        Err(e) => {
 470→            error!("failed to write shell RC: {e}");
 471→            return 1;
 472→        }
 473→    };
 474→
 475→    // Step 5: Create tmux session if not alive
 476→    if !backend.is_alive(&session_name) {
 477→        let source_cmd = shell::source_file_command(&rc_path);
 478→        if let Err(e) = backend.create_session(&session_name, &workspace_dir, Some(&source_cmd)) {
 479→            error!("session creation failed: {e}");
 480→            return 1;
 481→        }
 482→
 483→        // Set session-level env vars so new panes auto-source interception
 484→        let rc_path_str = rc_path.to_string_lossy();
 485→        for (key, value) in [
 486→            ("DUAL_ACTIVE", "1"),
 487→            ("DUAL_RC_PATH", rc_path_str.as_ref()),
 488→            ("DUAL_CONTAINER", container_name.as_str()),
 489→        ] {
 490→            if let Err(e) = dual::tmux_backend::set_session_env(&session_name, key, value) {
 491→                warn!("failed to set tmux env {key}: {e}");
 492→            }
 493→        }
 494→    }
 495→
 496→    // Step 6: Attach
 497→    info!("Attaching to {session_name}...");
 498→    if let Err(e) = backend.attach(&session_name) {
 499→        error!("attach failed: {e}");
 500→        return 1;
 501→    }
 502→
 503→    0
 504→}
