1001→/// "/Users/jeevan/code/lightfast" → "lightfast"
1002→fn derive_repo_name(path: &std::path::Path) -> String {
1003→    path.file_name()
1004→        .and_then(|n| n.to_str())
1005→        .unwrap_or("repo")
1006→        .to_string()
1007→}
