   282→# extra_commands = []
   283→
   284→# Directories to isolate with anonymous Docker volumes
   285→# These directories get their own volume so they don't sync between host/container
   286→# Example: anonymous_volumes = ["node_modules", ".next", "target"]
   287→# anonymous_volumes = ["node_modules"]
   288→
   289→# Files to share across all workspaces of this repo
   290→# These are gitignored files that should be available in every branch workspace
   291→# [shared]
   292→# files = [".env.local", ".vercel"]
   293→"#;
   294→    let hints_path = repo_root.join(HINTS_FILENAME);
   295→    std::fs::write(&hints_path, template).map_err(|e| HintsError::WriteError(hints_path, e))?;
   296→    Ok(())
   297→}
   298→
   299→/// Write a default devcontainer.json with minimal container config.
   300→/// Creates .devcontainer/ directory if it doesn't exist.
   301→pub fn write_default_devcontainer(repo_root: &Path) -> Result<(), HintsError> {
   302→    let dc_dir = repo_root.join(".devcontainer");
   303→    std::fs::create_dir_all(&dc_dir).map_err(|e| HintsError::WriteError(dc_dir.clone(), e))?;
   304→
   305→    let dc_path = dc_dir.join("devcontainer.json");
   306→    let content = r#"{
   307→    "image": "node:20"
   308→}
   309→"#;
   310→    std::fs::write(&dc_path, content).map_err(|e| HintsError::WriteError(dc_path, e))?;
   311→    Ok(())
   312→}
   313→
   314→/// Write DualConfig to a workspace directory's .dual.toml.
   315→pub fn write_dual_config(workspace_dir: &Path, config: &DualConfig) -> Result<(), HintsError> {
   316→    let path = workspace_dir.join(HINTS_FILENAME);
   317→    let contents = toml::to_string_pretty(config).map_err(HintsError::SerializeError)?;
   318→    std::fs::write(&path, contents).map_err(|e| HintsError::WriteError(path, e))?;
   319→    Ok(())
   320→}
   321→
   322→/// Parse DualConfig from TOML string (for testing).
   323→pub fn parse_dual_config(toml_str: &str) -> Result<DualConfig, HintsError> {
   324→    let config: DualConfig = toml::from_str(toml_str)
   325→        .map_err(|e| HintsError::ParseError(PathBuf::from("<string>"), e))?;
   326→    Ok(config)
   327→}
