   329→/// Compute the workspace identifier from repo + branch.
   330→/// e.g. ("lightfast", "feat/auth") → "lightfast-feat__auth"
   331→pub fn workspace_id(repo: &str, branch: &str) -> String {
   332→    format!("{}-{}", repo, encode_branch(branch))
   333→}
   334→
   335→/// Get the workspace directory for a repo + branch combination.
   336→/// Layout: {workspace_root}/{repo}/{encoded_branch}/
   337→pub fn workspace_dir(workspace_root: &Path, repo: &str, branch: &str) -> PathBuf {
   338→    workspace_root.join(repo).join(encode_branch(branch))
   339→}
   340→
   341→/// Compute the container name for a repo + branch combination.
   342→/// Pattern: dual-{repo}-{encoded_branch}
   343→pub fn container_name(repo: &str, branch: &str) -> String {
   344→    format!("dual-{}-{}", repo, encode_branch(branch))
   345→}
   346→
   347→/// Compute the tmux session name for a repo + branch combination.
   348→/// Uses the same naming convention as container names for consistency.
   349→pub fn session_name(repo: &str, branch: &str) -> String {
   350→    container_name(repo, branch)
   351→}
   352→
   353→/// Encode a branch name for filesystem use.
   354→/// Replaces `/` with `__` (double underscore).
   355→/// e.g. "feat/auth" → "feat__auth"
   356→pub fn encode_branch(branch: &str) -> String {
   357→    branch.replace('/', "__")
   358→}
   359→
   360→/// Decode an encoded branch name back to the original.
   361→/// Replaces `__` with `/`.
   362→/// e.g. "feat__auth" → "feat/auth"
   363→pub fn decode_branch(encoded: &str) -> String {
   364→    encoded.replace("__", "/")
   365→}
