   369→    #[error("Failed to read {path}: {err}", path = .0.display(), err = .1)]
   370→    ReadError(PathBuf, std::io::Error),
   371→
   372→    #[error("Failed to write {path}: {err}", path = .0.display(), err = .1)]
   373→    WriteError(PathBuf, std::io::Error),
   374→
   375→    #[error("Failed to parse {path}: {err}", path = .0.display(), err = .1)]
   376→    ParseError(PathBuf, toml::de::Error),
   377→
   378→    #[error("Failed to serialize hints: {0}")]
   379→    SerializeError(toml::ser::Error),
   380→}
