/// Start the reverse proxy.
fn cmd_proxy() -> i32 {
    let st = match state::load() {
        Ok(s) => s,
        Err(e) => {
            error!("{e}");
            return 1;
        }
    };

    let rt = tokio::runtime::Runtime::new().expect("failed to create tokio runtime");
    match rt.block_on(proxy::start(&st)) {
        Ok(()) => 0,
        Err(e) => {
            error!("proxy failed: {e}");
            1
        }
    }
}

